simplesect.para:
BAD_FUNC_ARG CTX構造がNULLの場合に返されます。 Example WOLFSSL_METHODmethod;//protocolmethod
WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(method);
…
longret=wolfSSL_CTX_get_verify_depth(ctx);

if(ret==EXPECTED){
//Youhavetheexpectedvalue
}else{
//Handleanunexpecteddepth
}

NULL 失敗すると。 Example WOLFSSL_CTX*ctx=0;
WOLFSSL_METHOD*method=0;

method=wolfSSLv3_client_method();
if(method==NULL){
//unabletogetmethod
}

ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}

NULL 失敗すると。 Example #include<wolfssl/ssl.h>

WOLFSSL*ssl=NULL;
WOLFSSL_CTX*ctx=0;

ctx=wolfSSL_CTX_new(method);
if(ctx==NULL){
//contextcreationfailed
}

ssl=wolfSSL_new(ctx);
if(ssl==NULL){
//SSLobjectcreationfailed
}

parameterdescription.para:
