プロトコル名のリストのサイズ。 Example wolfSSL_Init();
WOLFSSL_CTX*ctx;
WOLFSSL*ssl;
WOLFSSL_METHODmethod=//SomewolfSSLmethod
ctx=wolfSSL_CTX_new(method);
ssl=wolfSSL_new(ctx);

charalpn_list[]={};

if(wolfSSL_UseALPN(ssl,alpn_list,sizeof(alpn_list),
WOLFSSL_APN_FAILED_ON_MISMATCH)!=WOLFSSL_SUCCESS)
{
//Errorsettingsessionticket
}

simplesect.para:
