constchar*list="P-384:P-256";
...
ret=wolfSSL_CTX_set1_groups_list(ssl,list);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetgrouplist
}

BAD_FUNC_ARG ポインタパラメータがNULLの場合、グループ数はwolfssl_max_group_countを超えているか、TLS v1.3を使用していません。 Example intret;
WOLFSSL_CTX*ctx;
int*groups={WOLFSSL_ECC_X25519,WOLFSSL_ECC_SECP256R1};
intcount=2;
...
ret=wolfSSL_CTX_set1_groups_list(ctx,groups,count);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetgrouplist
}

BAD_FUNC_ARG ポインタパラメータがNULLの場合、グループ数がWolfSSL_MAX_GROUP_COUNTを超えている場合、任意の識別子は認識されないか、TLS v1.3を使用していません。 Example intret;
WOLFSSL*ssl;
int*groups={WOLFSSL_ECC_X25519,WOLFSSL_ECC_SECP256R1};
intcount=2;
...
ret=wolfSSL_set_groups(ssl,groups,count);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetgrouplist
}

SIDE_ERROR クライアントで呼び出された場合。 Example intret;
WOLFSSL_CTX*ctx;
...
ret=wolfSSL_CTX_set_max_early_data(ctx,128);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetgrouplist
}

SIDE_ERROR クライアントで呼び出された場合。 Example intret;
WOLFSSL*ssl;
...
ret=wolfSSL_set_max_early_data(ssl,128);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetgrouplist
}

