simplesect.para:
MEMORY_E 動的メモリ割り当てが失敗すると失敗すると。 Example intret;
WOLFSSL*ssl;
...
ret=wolfSSL_UseKeyShare(ssl,WOLFSSL_ECC_X25519);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetkeyshare
}

SIDE_ERROR サーバーで呼び出された場合。 Example intret;
WOLFSSL*ssl;
...
ret=wolfSSL_NoKeyShares(ssl);
if(ret!=WOLFSSL_SUCCESS){
//failedtosetnokeyshares
}

If 成功すると、呼び出しは新しく作成されたwolfssl_method構造体へのポインタを返します。 Example #include<wolfssl/ssl.h>

WOLFSSL_METHOD*method;
WOLFSSL_CTX*ctx;

method=wolfTLSv1_3_server_method_ex(NULL);
if(method==NULL){
//unabletogetmethod
}

ctx=wolfSSL_CTX_new(method);
...

If 成功すると、呼び出しは新しく作成されたwolfssl_method構造体へのポインタを返します。 Example #include<wolfssl/ssl.h>

WOLFSSL_METHOD*method;
WOLFSSL_CTX*ctx;

method=wolfTLSv1_3_client_method_ex(NULL);
if(method==NULL){
//unabletogetmethod
}

ctx=wolfSSL_CTX_new(method);
...

If 成功すると、呼び出しは新しく作成されたwolfssl_method構造体へのポインタを返します。 Example #include<wolfssl/ssl.h>

WOLFSSL_METHOD*method;
WOLFSSL_CTX*ctx;

method=wolfTLSv1_3_server_method();
if(method==NULL){
//unabletogetmethod
}

ctx=wolfSSL_CTX_new(method);
...

If 成功すると、呼び出しは新しく作成されたwolfssl_method構造体へのポインタを返します。 Example #include<wolfssl/ssl.h>

WOLFSSL_METHOD*method;
WOLFSSL_CTX*ctx;

method=wolfTLSv1_3_client_method();
if(method==NULL){
//unabletogetmethod
}

ctx=wolfSSL_CTX_new(method);
...

WOLFSSL_METHOD 成功した作成では、wolfssl_methodポインタを返します Example WOLFSSL*ctx;
ctx=wolfSSL_CTX_new(wolfTLSv1_3_method_ex(NULL));
//checkretvalue

WOLFSSL_METHOD 成功した作成では、wolfssl_methodポインタを返します Example WOLFSSL*ctx;
ctx=wolfSSL_CTX_new(wolfTLSv1_3_method());
//checkretvalue

NULL WolfSSL構造体がNULLの場合 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
WOLFSSL*ssl=wolfSSL_new(ctx);
void*cookie;
...
cookie=wolfSSL_GetCookieCtx(ssl);
if(cookie!=NULL){
//Youhavethecookie
}

